mapper.sql:

(
    configuration.scope = 'PERSONAL'
    AND configuration.tenant_id = #{tenantId}
    AND configuration.owner_membership_id = #{membershipId}
)
OR (
    configuration.scope = 'TENANT'
    AND configuration.tenant_id = #{tenantId}
)
OR (
    configuration.scope = 'PLATFORM'
    AND EXISTS (
        SELECT 1
        FROM model_runtime.model_configuration_access_grant access_grant
        WHERE access_grant.model_configuration_id = configuration.id
          AND access_grant.grantee_tenant_id = #{tenantId}
          AND access_grant.status = 'ACTIVE'
          AND (access_grant.grantee_membership_id IS NULL
               OR access_grant.grantee_membership_id = #{membershipId})
    )
)
